					["Scale"] = size
				}
			}
		}
		_(args)
	end

	function SetTransparency(part, value)
		local args = {
			[1] = "SyncTransparency",
			[2] = {
				[1] = {
					["Part"] = part,
					["Transparency"] = value
				}
			}
		}
		_(args)
	end

	function DestroyPart(part)
		local args = {
			[1] = "Remove",
			[2] = {
				[1] = part
			}
		}
		_(args)
	end

	local images = {
		"http://www.roblox.com/asset/?id=11660423541",
		"http://www.roblox.com/asset/?id=14684147782"
	}

	local skyPart
	local skyLoop
	local frameTime = 3.1 / 10
	local lastUpdate = 0

	function CreateSky()
		local hrp = char:FindFirstChild("HumanoidRootPart")
		if not hrp then return end

		local cf = hrp.CFrame
		CreatePart(CFrame.new(cf.Position + Vector3.new(0, 6, 0)), workspace)

		for _, v in workspace:GetDescendants() do
			if v:IsA("BasePart") and v.CFrame.Position == cf.Position + Vector3.new(0, 6, 0) then
				skyPart = v
				SetAnchor(skyPart, true)
				AddMesh(skyPart)
				SetMesh(skyPart, "111891702759441")
				MeshResize(skyPart, Vector3.new(8000, 8000, 8000))
				SetTransparency(skyPart, 1)

				local index = 1
				skyLoop = RunService.Heartbeat:Connect(function(deltaTime)
					lastUpdate = lastUpdate + deltaTime
					if lastUpdate >= frameTime then
						lastUpdate = 0
						if not skyPart then
							skyLoop:Disconnect()
							return
						end
						SetTransparency(skyPart, 0)
						SetTexture(skyPart, images[index])
						index = index % #images + 1
					end
				end)
			end
		end
	end

	function ResetSky()
		if skyPart then
			DestroyPart(skyPart)
			skyPart = nil
		end
		if skyLoop then
			skyLoop:Disconnect()
			skyLoop = nil
		end
		CreateSky()
	end

	player.CharacterAdded:Connect(function(newChar)
		char = newChar
		ResetSky()
	end)

	if char and char:FindFirstChild("Humanoid") then
		char:WaitForChild("Humanoid").Died:Connect(function()
			ResetSky()
		end)
	end

	CreateSky()
end)
